<?php require_once __DIR__.'/includes/config.php';require_login();$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT title,playlist_url,file_path FROM playlists WHERE id=?');$q->execute([$id]);$item=$q->fetch();if(!$item){http_response_code(404);exit('Not found');}if(isset($_GET['file'])&&$item['file_path']){$path=realpath(PLAYLIST_STORAGE.'/'.$item['file_path']);$root=realpath(PLAYLIST_STORAGE);if(!$path||!str_starts_with($path,$root)||!is_file($path)){http_response_code(404);exit('File unavailable');}header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="playlist-'.$id.'.m3u"');readfile($path);exit;}if($item['playlist_url']) redirect($item['playlist_url']);http_response_code(404);exit('Ссылка пока недоступна.');
